{
  "sql": "SELECT SUM(amount) AS value FROM ledger WHERE entity = 'Lakeside Energy' AND account_group = 'Revenue' AND month BETWEEN '2025-01' AND '2025-06'",
  "explanation": "Turnover is revenue. The query sums all revenue account amounts for Lakeside Energy from January 2025 through June 2025."
}

{
  "sql": "SELECT SUM(amount) AS value FROM ledger WHERE account_group = 'Revenue' AND month BETWEEN '2025-07' AND '2025-09' AND entity != 'North Hub'",
  "explanation": "Sums all revenue amounts for the third quarter of 2025, explicitly excluding the North Hub entity."
}

{
  "sql": "SELECT entity AS label, (SUM(CASE WHEN account_group = 'Revenue' THEN amount ELSE 0 END) - SUM(CASE WHEN account_group = 'Cost of sales' THEN amount ELSE 0 END) - SUM(CASE WHEN account_group = 'Operating expense' THEN amount ELSE 0 END)) AS value FROM ledger WHERE month IN ('2025-01', '2025-02', '2025-03') GROUP BY entity ORDER BY value ASC, label ASC LIMIT 3",
  "explanation": "Calculates operating profit (Revenue - Cost of sales - Operating expenses) for each entity in Q1 2025 (January to March 2025), groups by entity, and returns the three entities with the smallest values, breaking ties by entity name."
}

{
  "sql": "SELECT entity AS label, ROUND(100.0 * (SUM(CASE WHEN account_group = 'Revenue' THEN amount ELSE 0 END) - SUM(CASE WHEN account_group = 'Cost of sales' THEN amount ELSE 0 END)) / NULLIF(SUM(CASE WHEN account_group = 'Revenue' THEN amount ELSE 0 END), 0), 1) AS value FROM ledger WHERE month BETWEEN '2026-04' AND '2026-06' GROUP BY entity ORDER BY label ASC",
  "explanation": "Calculates gross margin for each entity in Q2 2026 (April-June) by summing revenue and cost of sales, applying the formula 100 * (Revenue - Cost of Sales) / Revenue, and handling zero revenue cases by returning 0."
}

{
  "sql": "SELECT SUM(amount) AS value FROM ledger WHERE account_group = 'Operating expense' AND month = '2025-11' AND entity != 'Harbour Retail'",
  "explanation": "Sums all operating expense amounts for November 2025, explicitly excluding the entity 'Harbour Retail' as requested."
}

{
  "sql": "SELECT CASE WHEN month IN ('2025-01','2025-02','2025-03') THEN '2025-Q1' WHEN month IN ('2025-04','2025-05','2025-06') THEN '2025-Q2' WHEN month IN ('2025-07','2025-08','2025-09') THEN '2025-Q3' WHEN month IN ('2025-10','2025-11','2025-12') THEN '2025-Q4' END AS label, SUM(CASE WHEN account_group = 'Revenue' THEN amount ELSE 0 END) - SUM(CASE WHEN account_group = 'Cost of sales' THEN amount ELSE 0 END) AS value FROM ledger WHERE entity = 'North Hub' AND month BETWEEN '2025-01' AND '2025-12' GROUP BY label ORDER BY label",
  "explanation": "Calculates gross profit (Revenue minus Cost of sales) for North Hub for each quarter in 2025 by grouping monthly data into quarters and summing the respective account groups."
}

{
  "sql": "SELECT ROUND(100.0 * (SUM(CASE WHEN account_group = 'Revenue' THEN amount ELSE 0 END) - SUM(CASE WHEN account_group = 'Cost of sales' THEN amount ELSE 0 END)) / NULLIF(SUM(CASE WHEN account_group = 'Revenue' THEN amount ELSE 0 END), 0), 1) AS value FROM ledger WHERE entity = 'Delta Services' AND month >= '2025-01' AND month <= '2025-12'",
  "explanation": "Calculates the gross margin for Delta Services for the full year 2025 by summing revenue and cost of sales, applying the formula (Revenue - Cost of Sales) / Revenue * 100, and rounding to one decimal place."
}

{
  "sql": "SELECT entity AS label, SUM(amount) AS value FROM ledger WHERE month = '2026-09' AND account_group = 'Revenue' GROUP BY entity ORDER BY value DESC, label ASC LIMIT 2",
  "explanation": "The query filters the ledger for September 2026 and the Revenue account group to calculate total sales for each entity. It groups by entity, orders the results by total sales in descending order (with entity name as a tie-breaker), and limits the output to the top two companies."
}

